      "title": "水中散歩教室",
      "summary": "高齢者や体力に自信のない方を対象にした「プールで歩く運動」です。水中での歩行運動は、膝や腰への負担が少なく、無理なく効果的に行えます。泳いだり、水に顔をつけたりすることはありません。",
